package com.campusevents.dao;
import com.campusevents.util.DatabaseConnection;import java.sql.*;import java.util.*;
public class RegistrationDAO {public String register(int student,int event)throws SQLException{try(Connection c=DatabaseConnection.get()){c.setAutoCommit(false);try{int cap,confirmed;String status,deadline;try(PreparedStatement p=c.prepareStatement("SELECT capacity,status,registration_deadline,(SELECT COUNT(*) FROM registrations WHERE event_id=? AND status='CONFIRMED') FROM events WHERE event_id=?")){p.setInt(1,event);p.setInt(2,event);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Event not found.");cap=r.getInt(1);status=r.getString(2);deadline=r.getString(3);confirmed=r.getInt(4);}}if(!status.equals("UPCOMING"))throw new SQLException("Event is not open for registration.");if(java.time.LocalDate.now().isAfter(java.time.LocalDate.parse(deadline)))throw new SQLException("Registration deadline has passed.");try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM registrations WHERE student_id=? AND event_id=?")){p.setInt(1,student);p.setInt(2,event);try(ResultSet r=p.executeQuery()){if(r.next())throw new SQLException("You already have a registration record for this event.");}}String id="REG-"+java.time.Year.now()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();String state=confirmed<cap?"CONFIRMED":"WAITLISTED";try(PreparedStatement p=c.prepareStatement("INSERT INTO registrations(registration_id,student_id,event_id,status) VALUES(?,?,?,?)")){p.setString(1,id);p.setInt(2,student);p.setInt(3,event);p.setString(4,state);p.executeUpdate();}c.commit();return id+"|"+state;}catch(SQLException e){c.rollback();throw e;}}}public void cancel(String reg,int student)throws SQLException{try(Connection c=DatabaseConnection.get()){c.setAutoCommit(false);try{int event;String state;try(PreparedStatement p=c.prepareStatement("SELECT event_id,status FROM registrations WHERE registration_id=? AND student_id=?")){p.setString(1,reg);p.setInt(2,student);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Registration not found.");event=r.getInt(1);state=r.getString(2);}}if(state.equals("CANCELLED"))throw new SQLException("Already cancelled.");try(PreparedStatement p=c.prepareStatement("UPDATE registrations SET status='CANCELLED' WHERE registration_id=?")){p.setString(1,reg);p.executeUpdate();}if(state.equals("CONFIRMED")){try(PreparedStatement p=c.prepareStatement("SELECT registration_id FROM registrations WHERE event_id=? AND status='WAITLISTED' ORDER BY registration_date,rowid LIMIT 1")){p.setInt(1,event);try(ResultSet r=p.executeQuery()){if(r.next())try(PreparedStatement u=c.prepareStatement("UPDATE registrations SET status='CONFIRMED' WHERE registration_id=?")){u.setString(1,r.getString(1));u.executeUpdate();}}}}c.commit();}catch(SQLException e){c.rollback();throw e;}}}public List<String[]> mine(int student)throws SQLException{List<String[]>a=new ArrayList<>();try(Connection c=DatabaseConnection.get();PreparedStatement p=c.prepareStatement("SELECT r.registration_id,e.title,e.event_date,e.venue,r.status,r.registration_date FROM registrations r JOIN events e ON e.event_id=r.event_id WHERE r.student_id=? ORDER BY r.registration_date DESC")){p.setInt(1,student);try(ResultSet r=p.executeQuery()){while(r.next())a.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6)});}}return a;}public List<String[]> participants(int event)throws SQLException{List<String[]>a=new ArrayList<>();try(Connection c=DatabaseConnection.get();PreparedStatement p=c.prepareStatement("SELECT s.college_id,u.name,u.email,r.registration_id,r.status FROM registrations r JOIN students s ON s.student_id=r.student_id JOIN users u ON u.user_id=s.user_id WHERE r.event_id=? ORDER BY r.registration_date")){p.setInt(1,event);try(ResultSet r=p.executeQuery()){while(r.next())a.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)});}}return a;}}
